Definition dbp_locals1 (a4w : word) (E ff : Z) (j0 j32 j64 : list byte) : list cell :=
  [CB 16 j0; C8 a4w; C8 (wz E); CB 24 j32; C8 (wz ff); CB 24 j64].

(* [comment removed for export] *)
Definition dbp_ffa (spa : Z) : list cell :=
  [C8 (Z_to_bv 64 0x41b58ab3); C8 (Z_to_bv 64 0x15b82); C8 (Z_to_bv 64 0xbd6fc); C8 (Z_to_bv 64 spa)].

(* [comment removed for export] *)
Definition dbp_sh1 : list cell :=
  [C1 (b8 (-15 mod 256)); C1 (b8 (-15 mod 256)); C1 (b8 (-15 mod 256)); C1 (b8 (-15 mod 256));
   C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
